function validate([start, target, specialRoads]) {
  const whole = v => Number.isInteger(v);
  if (!Array.isArray(start) || start.length !== 2 || !start.every(whole)) return 'start is a pair of whole numbers.';
  if (!Array.isArray(target) || target.length !== 2 || !target.every(whole)) return 'target is a pair of whole numbers.';
  const [startX, startY] = start, [targetX, targetY] = target;
  if (startX < 1 || targetX > 100000 || startX > targetX) return 'Need 1 <= startX <= targetX <= 10^5.';
  if (startY < 1 || targetY > 100000 || startY > targetY) return 'Need 1 <= startY <= targetY <= 10^5.';
  if (!Array.isArray(specialRoads) || specialRoads.length < 1 || specialRoads.length > 200) return 'specialRoads needs 1 to 200 roads.';
  for (const road of specialRoads) {
    if (!Array.isArray(road) || road.length !== 5 || !road.every(whole)) return 'Each road is five whole numbers [x1, y1, x2, y2, cost].';
    const [x1, y1, x2, y2, cost] = road;
    if (x1 < startX || x1 > targetX || x2 < startX || x2 > targetX) return 'Road x coordinates stay between startX and targetX.';
    if (y1 < startY || y1 > targetY || y2 < startY || y2 > targetY) return 'Road y coordinates stay between startY and targetY.';
    if (cost < 1 || cost > 100000) return 'Each road cost is from 1 to 10^5.';
  }
  return null;
}

