function minimumCost(start, target, specialRoads) {
  const walk = (x1, y1, x2, y2) => Math.abs(x1 - x2) + Math.abs(y1 - y2);
  const [startX, startY] = start;
  const [targetX, targetY] = target;
  const m = specialRoads.length;

  // dist[i] is the cheapest known cost of standing at the end of road i.
  const dist = [];
  for (const [x1, y1, , , cost] of specialRoads) {
    dist.push(walk(startX, startY, x1, y1) + cost);
  }
  const done = new Array(m).fill(false);
  let best = walk(startX, startY, targetX, targetY);

  for (let round = 0; round < m; round++) {
    let u = -1;
    for (let i = 0; i < m; i++) {
      if (!done[i] && (u === -1 || dist[i] < dist[u])) {
        u = i;
      }
    }
    done[u] = true;
    const [, , endX, endY] = specialRoads[u];
    best = Math.min(best, dist[u] + walk(endX, endY, targetX, targetY));

    for (let v = 0; v < m; v++) {
      const [x1, y1, , , cost] = specialRoads[v];
      const through = dist[u] + walk(endX, endY, x1, y1) + cost;
      if (through < dist[v]) {
        dist[v] = through;
      }
    }
  }
  return best;
}

