function minimumCost(start, target, specialRoads) {
  // Floyd-Warshall over every interesting point: start, target and both ends of each road.
  const points = [start, target];
  for (const [x1, y1, x2, y2] of specialRoads) points.push([x1, y1], [x2, y2]);
  const size = points.length;
  const d = points.map(([ax, ay]) => points.map(([bx, by]) => Math.abs(ax - bx) + Math.abs(ay - by)));
  specialRoads.forEach(([, , , , cost], i) => {
    const from = 2 + 2 * i, to = from + 1;
    d[from][to] = Math.min(d[from][to], cost);
  });
  for (let k = 0; k < size; k++)
    for (let i = 0; i < size; i++)
      for (let j = 0; j < size; j++)
        if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
  return d[0][1];
}

