function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const startX = large ? pick(1, 1000) : pick(1, 5);
  const startY = large ? pick(1, 1000) : pick(1, 5);
  const targetX = startX + (large ? pick(50000, 100000 - startX) : pick(0, 8));
  const targetY = startY + (large ? pick(50000, 100000 - startY) : pick(0, 8));
  const m = large ? 200 : pick(1, 6);
  const roads = [];
  for (let i = 0; i < m; i++) {
    const x1 = pick(startX, targetX), y1 = pick(startY, targetY), x2 = pick(startX, targetX), y2 = pick(startY, targetY);
    const length = Math.abs(x1 - x2) + Math.abs(y1 - y2);
    // Mix shortcuts that beat walking with roads that are not worth taking.
    const cost = rand() < 0.6 ? Math.max(1, Math.floor(length * (0.05 + rand() * 0.6))) : pick(1, large ? 100000 : 15);
    roads.push([x1, y1, x2, y2, Math.min(cost, 100000)]);
  }
  return [[startX, startY], [targetX, targetY], roads];
}
